3	/**
4	 * Single source of truth for the owner telephone normalization rule, shared by the
5	 * owner-create pipeline. The uniqueness check only holds if both the value stored for a
6	 * new owner and the values compared against existing owners are normalized identically,
7	 * so that rule lives here rather than being duplicated across steps.
8	 */
9	final class OwnerTelephone {
10	
11	    private OwnerTelephone() {
12	    }
13	
14	    /**
15	     * Normalize a telephone to E.164 form, or {@code null} if the input is {@code null} or
16	     * cannot form a valid E.164 number.
17	     *
18	     * <p>Spaces, dashes and brackets are stripped. A leading {@code '+'} and country code are
19	     * kept when present; otherwise the country code {@code '+61'} is assumed and a single
20	     * leading {@code '0'} is dropped from the national digits. The result is valid only when
21	     * it has 8 to 15 digits after the {@code '+'}; anything else (including stray non-digit
22	     * characters) yields {@code null}. In addition, for a recognised country code the
23	     * national number (the digits after the country code) must have the exact length that
24	     * country requires — {@code '+61'} requires 9 national digits and {@code '+1'} requires
25	     * 10 — otherwise the result is {@code null}. The function is idempotent: an already-E.164
26	     * value normalizes to itself.
27	     */
28	    static String normalize(String telephone) {
29	        if (telephone == null) {
30	            return null;
31	        }
32	        String cleaned = telephone.replaceAll("[\\s()-]", "");
33	        boolean hasPlus = cleaned.startsWith("+");
34	        String digits = hasPlus ? cleaned.substring(1) : cleaned;
35	        if (!digits.matches("[0-9]+")) {
36	            return null;
37	        }
38	        String e164Digits;
39	        if (hasPlus) {
40	            e164Digits = digits;
41	        }
42	        else {
43	            String national = digits.startsWith("0") ? digits.substring(1) : digits;
44	            e164Digits = "61" + national;
45	        }
46	        if (e164Digits.length() < 8 || e164Digits.length() > 15) {
47	            return null;
48	        }
49	        if (!hasValidNationalLength(e164Digits)) {
50	            return null;
51	        }
52	        return "+" + e164Digits;
53	    }
54	
55	    /**
56	     * For a recognised country code, require the exact national-number length that country
57	     * uses. {@code '+61'} expects 9 national digits and {@code '+1'} expects 10. Unrecognised
58	     * country codes are left to the generic 8-to-15 digit length check.
59	     */
60	    private static boolean hasValidNationalLength(String e164Digits) {
61	        if (e164Digits.startsWith("61")) {
62	            return e164Digits.length() - 2 == 9;
63	        }
64	        if (e164Digits.startsWith("1")) {
65	            return e164Digits.length() - 1 == 10;
66	        }
67	        return true;
68	    }
69	}
