15	
16	public class BuildOwner {
17	
18	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
19	            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
20	        Owner owner = ownerMapper.toOwner(request);
21	        // The effective registration date defaults an unsupplied value to the server's
22	        // current date, then rolls any weekend forward to the next Monday so derived values
23	        // (e.g. the membership number's year) use the adjusted business day.
24	        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
25	        owner.setCustomerCode(deduplicate(customerCode(owner), ownerRepository));
26	        // Record how many existing owners already share this first+last name (case-insensitive),
27	        // counted before this owner is persisted so the value is fixed at creation time.
28	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
29	        // Join a shared household when the gate resolved an identifier.
30	        if (householdId != null && householdId.isPresent()) {
31	            owner.setHouseholdId(householdId.value());
32	        }
33	        // Record the household's member count (existing members plus this not-yet-persisted
34	        // owner) so the membership points rule can score a household of 3 or more.
35	        owner.setHouseholdSize(Household.size(owner.getHouseholdId(), ownerRepository) + 1);
36	        built.set(owner);
37	    }
38	
39	    /**
40	     * Build the '<REGION>-<HASH8>' customer code: REGION is the region derived from the owner's
41	     * postcode and city ({@link Owner#regionFor(String, String)}, e.g. 'NSW' or 'UNKNOWN'), and
42	     * HASH8 is the first 8 upper-case hex characters of the SHA-256 of the normalized telephone
43	     * followed by the last name (e.g. 'NSW-1A2B3C4D'). There is no sequence number, so the code
44	     * is stable for an owner regardless of creation order.
45	     */
46	    private static String customerCode(Owner owner) {
47	        String region = Owner.regionFor(owner.getPostcode(), owner.getCity());
48	        String normalizedTelephone = OwnerTelephone.normalize(owner.getTelephone());
49	        String seed = (normalizedTelephone == null ? "" : normalizedTelephone) + owner.getLastName();
50	        return region + "-" + hash8(seed);
51	    }
52	
53	    /**
54	     * Return a customerCode that no existing owner already uses. When {@code code} collides with an
55	     * existing owner's customerCode, append '-&lt;n&gt;' with the smallest n of 2 or more that makes
56	     * it unique (e.g. 'NSW-1A2B3C4D' → 'NSW-1A2B3C4D-2'). The un-suffixed code is returned unchanged
57	     * when it does not collide.
58	     */
59	    private static String deduplicate(String code, OwnerRepository ownerRepository) {
60	        Set<String> existing = new HashSet<>();
61	        for (Owner owner : ownerRepository.findAll()) {
62	            if (owner.getCustomerCode() != null) {
63	                existing.add(owner.getCustomerCode());
